pub fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    let m = arr.len();
    let n = arr[0].len();

    // If there are zero columns, the transpose has zero rows.
    if n == 0 {
        return Vec::new();
    }

    // Create n rows, each will end up with m elements.
    let mut out: Vec<Vec<i8>> = (0..n).map(|_| Vec::with_capacity(m)).collect();

    for i in 0..m {
        debug_assert_eq!(arr[i].len(), n, "Input must be rectangular");
        for j in 0..n {
            out[j].push(arr[i][j]);
        }
    }

    out
}